draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // Draw a fruit
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // Draw a leaf
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2 + 60, H/2 - 40, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // Draw a stick figure eating
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 20);
  ctx.lineTo(W/2 - 100, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 50);
  ctx.lineTo(W/2 - 120, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 50);
  ctx.lineTo(W/2 - 80, H/2 + 70);
  ctx.stroke();

  // Animate the stick figure's arm
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 50);
  ctx.lineTo(W/2 - 80 + 20*Math.sin(t), H/2 + 70);
  ctx.stroke();

  ctx.restore();
}
